#!/usr/bin/env python3
"""Generate the Python accessors for the FACTORY part of ``hwlink.fbs``.

The canonical schema is normally compiled with ``flatc --python``.  This
repository builds the *same* module layout without the compiler so that the
factory protocol (protocol minor 4) can be developed and tested on machines
that only have the FlatBuffers runtime.  The generated files carry the same
"automatically generated" banner and expose the same API as flatc output:

    Table.Field() / Table.FieldLength() / Table.FieldIsNone()
    TableStart(builder) / TableAddField(builder, value) / TableEnd(builder)

Run ``python scripts/gen_factory_fb.py`` after editing the FACTORY tables in
``src/hostcore/protocol/hwlink.fbs``.  It only writes the FACTORY tables; the
rest of the generated package is untouched.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "src/hostcore/protocol/generated/hwlink"
BANNER = "# automatically generated by the FlatBuffers compiler, do not modify"
IDENT = r'b"\x48\x57\x4C\x4B"'


@dataclass(frozen=True)
class Field:
    name: str
    kind: str          # scalar type or "string", "ubyte_vec", "table_vec"
    table: str = ""    # element type for table_vec


@dataclass(frozen=True)
class Table:
    name: str
    fields: tuple[Field, ...]


SCALARS = {
    "bool": ("BoolFlags", "PrependBoolSlot", "False"),
    "ubyte": ("Uint8Flags", "PrependUint8Slot", "0"),
    "uint16": ("Uint16Flags", "PrependUint16Slot", "0"),
    "uint32": ("Uint32Flags", "PrependUint32Slot", "0"),
}

TABLES = (
    Table("GetFactoryInfo", ()),
    Table("FactoryInfo", (
        Field("firmware_name", "string"),
        Field("version", "string"),
        Field("build", "string"),
        Field("uid", "ubyte_vec"),
        Field("flash_mode", "ubyte"),
        Field("window_base", "uint32"),
        Field("window_end", "uint32"),
        Field("max_chunk", "uint16"),
    )),
    Table("ReadMemory", (
        Field("address", "uint32"),
        Field("length", "uint16"),
    )),
    Table("MemoryData", (
        Field("address", "uint32"),
        Field("data", "ubyte_vec"),
    )),
    Table("FactoryWriteBegin", (
        Field("kind", "ubyte"),
        Field("address", "uint32"),
        Field("total", "uint16"),
        Field("crc32", "uint32"),
    )),
    Table("FactoryWriteData", (
        Field("offset", "uint16"),
        Field("data", "ubyte_vec"),
    )),
    Table("FactoryWriteEnd", ()),
    Table("FactoryWriteResult", (
        Field("success", "bool"),
        Field("crc32", "uint32"),
        Field("error", "uint16"),
        Field("detail", "string"),
    )),
    Table("FactoryDiagInit", (
        Field("address", "uint32"),
    )),
    Table("FactorySelfTest", ()),
    Table("SelfTestItem", (
        Field("check", "ubyte"),
        Field("result", "ubyte"),
        Field("value", "uint32"),
    )),
    Table("SelfTestResult", (
        Field("items", "table_vec", "SelfTestItem"),
    )),
)


def camel(name: str) -> str:
    return "".join(part.capitalize() for part in name.split("_"))


def accessor(index: int, field: Field) -> str:
    label = camel(field.name)
    offset = 4 + 2 * index
    if field.kind == "string":
        return f"""    # {label}
    def {label}(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            return self._tab.String(o + self._tab.Pos)
        return None
"""
    if field.kind == "ubyte_vec":
        return f"""    # {label}
    def {label}(self, j):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            a = self._tab.Vector(o)
            return self._tab.Get(flatbuffers.number_types.Uint8Flags, a + flatbuffers.number_types.UOffsetTFlags.py_type(j * 1))
        return 0

    # {label}
    def {label}AsNumpy(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            return self._tab.GetVectorAsNumpy(flatbuffers.number_types.Uint8Flags, o)
        return 0

    # {label}
    def {label}Length(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            return self._tab.VectorLen(o)
        return 0

    # {label}
    def {label}IsNone(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        return o == 0
"""
    if field.kind == "table_vec":
        return f"""    # {label}
    def {label}(self, j):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            x = self._tab.Vector(o)
            x += flatbuffers.number_types.UOffsetTFlags.py_type(j) * 4
            x = self._tab.Indirect(x)
            from .{field.table} import {field.table}
            obj = {field.table}()
            obj.Init(self._tab.Bytes, x)
            return obj
        return None

    # {label}
    def {label}Length(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            return self._tab.VectorLen(o)
        return 0

    # {label}
    def {label}IsNone(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        return o == 0
"""
    flags, _prepend, default = SCALARS[field.kind]
    return f"""    # {label}
    def {label}(self):
        o = flatbuffers.number_types.UOffsetTFlags.py_type(self._tab.Offset({offset}))
        if o != 0:
            return self._tab.Get(flatbuffers.number_types.{flags}, o + self._tab.Pos)
        return {default}
"""


def builder_functions(tname: str, index: int, field: Field) -> str:
    label = camel(field.name)
    name = field.name
    if field.kind == "string":
        add = (
            f"def {tname}Add{label}(builder, {name}): "
            f"builder.PrependUOffsetTRelativeSlot({index}, flatbuffers.number_types.UOffsetTFlags.py_type({name}), 0)"
        )
        extra = ""
    elif field.kind == "ubyte_vec":
        add = (
            f"def {tname}Add{label}(builder, {name}): "
            f"builder.PrependUOffsetTRelativeSlot({index}, flatbuffers.number_types.UOffsetTFlags.py_type({name}), 0)"
        )
        extra = (
            f"\n\ndef {tname}Start{label}Vector(builder, numElems): "
            f"return builder.StartVector(1, numElems, 1)"
            f"\n\ndef Start{label}Vector(builder, numElems):\n"
            f"    return {tname}Start{label}Vector(builder, numElems)\n"
        )
    elif field.kind == "table_vec":
        add = (
            f"def {tname}Add{label}(builder, {name}): "
            f"builder.PrependUOffsetTRelativeSlot({index}, flatbuffers.number_types.UOffsetTFlags.py_type({name}), 0)"
        )
        extra = (
            f"\n\ndef {tname}Start{label}Vector(builder, numElems): "
            f"return builder.StartVector(4, numElems, 4)"
            f"\n\ndef Start{label}Vector(builder, numElems):\n"
            f"    return {tname}Start{label}Vector(builder, numElems)"
            f"\n\ndef {tname}Create{label}Vector(builder, data):\n"
            f"    return builder.CreateVectorOfTables(data)\n"
            f"\n\ndef Create{label}Vector(builder, data):\n"
            f"    {tname}Create{label}Vector(builder, data)\n"
        )
    else:
        _flags, prepend, default = SCALARS[field.kind]
        add = f"def {tname}Add{label}(builder, {name}): builder.{prepend}({index}, {name}, {default})"
        extra = ""
    return f"""{add}
def Add{label}(builder, {name}):
    {tname}Add{label}(builder, {name})
{extra}"""


def module(table: Table) -> str:
    tname = table.name
    body = "".join(accessor(i, field) for i, field in enumerate(table.fields))
    builders = "".join(builder_functions(tname, i, field) for i, field in enumerate(table.fields))
    return f'''{BANNER}

# namespace: hwlink

import flatbuffers
from flatbuffers.compat import import_numpy
np = import_numpy()

class {tname}(object):
    __slots__ = ['_tab']

    @classmethod
    def GetRootAs(cls, buf, offset=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, offset)
        x = {tname}()
        x.Init(buf, n + offset)
        return x

    @classmethod
    def GetRootAs{tname}(cls, buf, offset=0):
        """This method is deprecated. Please switch to GetRootAs."""
        return cls.GetRootAs(buf, offset)
    @classmethod
    def {tname}BufferHasIdentifier(cls, buf, offset, size_prefixed=False):
        return flatbuffers.util.BufferHasIdentifier(buf, offset, {IDENT}, size_prefixed=size_prefixed)

    # {tname}
    def Init(self, buf, pos):
        self._tab = flatbuffers.table.Table(buf, pos)

{body}
def {tname}Start(builder):
    builder.StartObject({len(table.fields)})

def Start(builder):
    {tname}Start(builder)

{builders}def {tname}End(builder):
    return builder.EndObject()

def End(builder):
    return {tname}End(builder)
'''


def main() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    for table in TABLES:
        (OUT / f"{table.name}.py").write_text(module(table), encoding="utf-8")
    print(f"wrote {len(TABLES)} modules to {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
